  const doLivro = String(claim[campo]);
  return {
    texto: campo === 'unit' ? unidadeDaLinha(claim.unit, lang).texto : doLivro,
    livro: doLivro,
    origem: 'linha',
    linha: claim.id,
    campo,
    unidade: claim.unit ?? null,
    periodo: claim.reference_date ?? null,
  };
}

